// Error Trigger ส่งข้อมูลสองแบบ แบบแรกเมื่อ node ใดพังระหว่างทำงาน (มี execution)
// แบบที่สองเมื่อ trigger พังก่อนเริ่ม execution (มี trigger แทน)
const d = $json;
const exec = d.execution ?? {};
const err = exec.error ?? d.trigger?.error ?? {};
const when = DateTime.now().setZone('Asia/Bangkok').toFormat('dd/MM/yyyy HH:mm:ss');
return { json: {
  workflow_id: d.workflow?.id ?? '',
  workflow_name: d.workflow?.name ?? '(ไม่ทราบชื่อ)',
  execution_id: exec.id ?? '',
  execution_url: exec.url ?? '',
  failed_node: exec.lastNodeExecuted ?? err.node?.name ?? '',
  // ตัดข้อความ error ให้สั้น และไม่แนบข้อมูลที่ผู้ใช้ส่งเข้ามา เพราะอาจมีข้อมูลส่วนบุคคล
  message: String(err.message ?? 'ไม่มีข้อความ error').slice(0, 500),
  mode: exec.mode ?? 'trigger',
  when,
} };

